B.aqA=new A.px("Welcome to Arabic Step by Step","\u0645\u064e\u0631\u0652\u062d\u064e\u0628\u064b\u0627 \u0628\u0650\u0643\u064e \u0641\u0650\u064a \xab\u0627\u0644\u0652\u0639\u064e\u0631\u064e\u0628\u0650\u064a\u064e\u0651\u0629\u0650 \u062e\u064f\u0637\u0652\u0648\u064e\u0629\u064b \u062e\u064f\u0637\u0652\u0648\u064e\u0629\u064b\xbb",B.a0K)
B.Tg=s(["Lesson 0 \xb7 Reading the script and its sounds (optional)","\u0627\u0644\u062f\u064e\u0651\u0631\u0652\u0633\u064f \u0660 \xb7 \u0642\u0650\u0631\u064e\u0627\u0621\u064e\u0629\u064f \u0627\u0644\u0652\u062d\u064f\u0631\u064f\u0648\u0641\u0650 \u0648\u064e\u0623\u064e\u0635\u0652\u0648\u064e\u0627\u062a\u064f\u0647\u064e\u0627 (\u0627\u0650\u062e\u0652\u062a\u0650\u064a\u064e\u0627\u0631\u0650\u064a\u064c\u0651)"],t.s)
B.Y_=s(["Level 1 \xb7 Lessons 1\u201310 \xb7 The sentence and the noun","\u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0648\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0648\u064e\u0651\u0644\u064f \xb7 \u0627\u0644\u062f\u064f\u0651\u0631\u064f\u0648\u0633\u064f \u0661\u2013\u0661\u0660 \xb7 \u0627\u0644\u0652\u062c\u064f\u0645\u0652\u0644\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0650\u0627\u0633\u0652\u0645\u064f"],t.s)
B.U3=s(["Level 2 \xb7 Lessons 11\u201320 \xb7 Possession, number and the present tense","\u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0648\u064e\u0649 \u0627\u0644\u062b\u064e\u0651\u0627\u0646\u0650\u064a \xb7 \u0627\u0644\u062f\u064f\u0651\u0631\u064f\u0648\u0633\u064f \u0661\u0661\u2013\u0662\u0660 \xb7 \u0627\u0644\u0652\u0625\u0650\u0636\u064e\u0627\u0641\u064e\u0629\u064f \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u062f\u064e\u062f\u064f \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0636\u064e\u0627\u0631\u0650\u0639\u064f"],t.s)
B.TW=s(["Level 3 \xb7 Lessons 21\u201330 \xb7 Negation, commands and the sentence modifiers","\u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0648\u064e\u0649 \u0627\u0644\u062b\u064e\u0651\u0627\u0644\u0650\u062b\u064f \xb7 \u0627\u0644\u062f\u064f\u0651\u0631\u064f\u0648\u0633\u064f \u0662\u0661\u2013\u0663\u0660 \xb7 \u0627\u0644\u0646\u064e\u0651\u0641\u0652\u064a\u064f \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064f \u0648\u064e\u0646\u064e\u0648\u064e\u0627\u0633\u0650\u062e\u064f \u0627\u0644\u0652\u062c\u064f\u0645\u0652\u0644\u064e\u0629\u0650"],t.s)
B.Um=s(["Level 4 \xb7 Lessons 31\u201340 \xb7 The verb system","\u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0648\u064e\u0649 \u0627\u0644\u0631\u064e\u0651\u0627\u0628\u0650\u0639\u064f \xb7 \u0627\u0644\u062f\u064f\u0651\u0631\u064f\u0648\u0633\u064f \u0663\u0661\u2013\u0664\u0660 \xb7 \u0646\u0650\u0638\u064e\u0627\u0645\u064f \u0627\u0644\u0652\u0641\u0650\u0639\u0652\u0644\u0650"],t.s)
B.a__=s(["Level 5 \xb7 Lessons 41\u201350 \xb7 The man\u1e63\u016bb\u0101t and the complex sentence","\u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0648\u064e\u0649 \u0627\u0644\u0652\u062e\u064e\u0627\u0645\u0650\u0633\u064f \xb7 \u0627\u0644\u062f\u064f\u0651\u0631\u064f\u0648\u0633\u064f \u0664\u0661\u2013\u0665\u0660 \xb7 \u0627\u0644\u0652\u0645\u064e\u0646\u0652\u0635\u064f\u0648\u0628\u064e\u0627\u062a\u064f \u0648\u064e\u0627\u0644\u0652\u062c\u064f\u0645\u0652\u0644\u064e\u0629\u064f \u0627\u0644\u0652\u0645\u064f\u0631\u064e\u0643\u064e\u0651\u0628\u064e\u0629\u064f"],t.s)
B.Vj=s(["Level 6 \xb7 Lessons 51\u201360 \xb7 Real texts: Qur\u2019an, \u1e25ad\u012bth, classical prose","\u0627\u0644\u0652\u0645\u064f\u0633\u0652\u062a\u064e\u0648\u064e\u0649 \u0627\u0644\u0633\u064e\u0651\u0627\u062f\u0650\u0633\u064f \xb7 \u0627\u0644\u062f\u064f\u0651\u0631\u064f\u0648\u0633\u064f \u0665\u0661\u2013\u0666\u0660 \xb7 \u0646\u064f\u0635\u064f\u0648\u0635\u064c \u062d\u064e\u0642\u0650\u064a\u0642\u0650\u064a\u064e\u0651\u0629\u064c: \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062b\u064f \u0648\u064e\u0627\u0644\u0646\u064e\u0651\u062b\u0652\u0631\u064f \u0627\u0644\u0652\u0642\u064e\u062f\u0650\u064a\u0645\u064f"],t.s)
B.TK=s(["After the course: Read and Understand \u2014 61 graded readings of real texts (Readings 40\u2013100).","\u0648\u064e\u0628\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0652\u0645\u064f\u0642\u064e\u0631\u064e\u0651\u0631\u0650: \xab\u0627\u0650\u0642\u0652\u0631\u064e\u0623\u0652 \u0648\u064e\u0627\u0641\u0652\u0647\u064e\u0645\u0652\xbb \u2014 \u0648\u064e\u0627\u062d\u0650\u062f\u064c \u0648\u064e\u0633\u0650\u062a\u064f\u0651\u0648\u0646\u064e \u0646\u064e\u0635\u064b\u0651\u0627 \u0645\u064f\u062a\u064e\u062f\u064e\u0631\u0650\u0651\u062c\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u064f\u0651\u0635\u064f\u0648\u0635\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0650\u064a\u0642\u0650\u064a\u064e\u0651\u0629\u0650 (\u0627\u0644\u0652\u0642\u0650\u0631\u064e\u0627\u0621\u064e\u0627\u062a\u064f \u0664\u0660\u2013\u0661\u0660\u0660)."],t.s)
